package com.teamflow.planning.service;
import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import com.teamflow.planning.api.*; import com.teamflow.planning.repository.PlanningRepository; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class PlanningService {
 private final PlanningRepository repo; private final ObjectMapper mapper; public PlanningService(PlanningRepository r,ObjectMapper m){repo=r;mapper=m;}
 public AllocationResponse create(UUID org,AllocationRequest r){validateResource(r.resourceType());validateDates(r.startDate(),r.endDate());return repo.saveAllocation(org,new AllocationRequest(r.projectId(),r.resourceType().toUpperCase(),r.resourceId(),r.startDate(),r.endDate(),r.fixed()));}
 public List<AllocationResponse> list(UUID org,UUID p,String t,UUID res,LocalDate from,LocalDate to){return repo.allocations(org,p,t,res,from,to);}
 public void fixed(UUID org,UUID id,boolean value){repo.setFixed(org,id,value);} public void cancel(UUID org,UUID id){repo.cancel(org,id);}
 public TransportResponse transport(UUID org,TransportRequest r){validateResource(r.resourceType());if(r.durationDays()!=null&&r.durationDays()<1)throw new IllegalArgumentException("durationDays must be positive");return repo.saveTransport(org,new TransportRequest(r.resourceType().toUpperCase(),r.resourceId(),r.origin().trim(),r.destination().trim(),r.startDate(),r.durationDays()));}
 public List<TransportResponse> transports(UUID org){return repo.transports(org);}
 public List<ConflictResponse> conflicts(UUID org,AllocationRequest r){validateResource(r.resourceType());validateDates(r.startDate(),r.endDate());String type=r.resourceType().toUpperCase();var result=new ArrayList<ConflictResponse>();for(var a:repo.allocations(org,null,type,r.resourceId(),r.startDate(),r.endDate()))if(!a.status().equals("CANCELLED")&&a.startDate().isBefore(r.endDate().plusDays(1))&&r.startDate().isBefore(a.endDate().plusDays(1)))result.add(new ConflictResponse("OVERLAPPING_ALLOCATION","BLOCKING",type,r.resourceId(),r.startDate(),r.endDate(),"O recurso já possui uma alocação sobreposta.","Escolha outro recurso ou período."));for(var t:repo.transports(org))if(t.resourceType().equals(type)&&t.resourceId().equals(r.resourceId())&&t.status().equals("PENDING"))result.add(new ConflictResponse("TRANSPORT_PENDING","PLANNING_PENDING",type,r.resourceId(),t.startDate(),t.arrivalDate(),"Há um deslocamento identificado sem duração definida.","Informe a duração e confirme o transporte."));return result;}
 public ProposalResponse proposal(UUID org){try{return repo.proposal(org,mapper.writeValueAsString(Map.of("strategy","priority-deadline-greedy","status","DRAFT")));}catch(JsonProcessingException e){throw new IllegalStateException(e);}}
 public void approve(UUID org,UUID id){repo.approve(org,id);} private void validateDates(LocalDate s,LocalDate e){if(e.isBefore(s))throw new IllegalArgumentException("endDate must be on or after startDate");} private void validateResource(String type){if(type==null||!(type.equalsIgnoreCase("TEAM")||type.equalsIgnoreCase("EMPLOYEE")))throw new IllegalArgumentException("resourceType must be TEAM or EMPLOYEE");}
}
